    73	ghost function MaxFirst(s: seq<(int, int)>): int
    74	  requires |s| > 0
    75	  decreases |s|
    76	{
    77	  if |s| == 1 then s[0].0
    78	  else var m := MaxFirst(s[1..]); if s[0].0 > m then s[0].0 else m
    79	}
