    81	lemma MaxFirstBounds(s: seq<(int, int)>)
    82	  requires |s| > 0
    83	  ensures forall x :: x in s ==> x.0 <= MaxFirst(s)
    84	  decreases |s|
    85	{
    86	  if |s| == 1 {
    87	    forall x | x in s ensures x.0 <= MaxFirst(s) { assert x == s[0]; }
    88	  } else {
    89	    MaxFirstBounds(s[1..]);
    90	    forall x | x in s ensures x.0 <= MaxFirst(s) {
    91	      if x != s[0] {
    92	        var i :| 0 <= i < |s| && s[i] == x;
    93	        if i > 0 { assert s[1..][i-1] == x; assert x in s[1..]; }
    94	      }
    95	    }
    96	  }
    97	}
