    99	// The point of the exercise: the sorted sequence's last first-component is
   100	// MaxFirst of the INPUT. Before prelude.dfy had SortIsSorted and SortLastIsMax
   101	// this could not be stated at all, because nothing said Sort produced an
   102	// ordered sequence -- only that it was a permutation.
   103	//
   104	// `less` is a parameter rather than a named constant on purpose: a ghost
   105	// function returning a lambda gives Dafny a value it will not identify with
   106	// the same lambda written at the call site, and every fact about Sort then
   107	// fails to transfer.
   108	lemma LastIsMaxFirst(pairs: seq<(int, int)>, less: ((int, int), (int, int)) -> bool)
   109	  requires |pairs| > 0
   110	  requires StrictTotalOrder(less)
   111	  requires forall a: (int, int), b: (int, int) :: !less(a, b) ==> b.0 <= a.0
   112	  ensures |Sort(pairs, less)| == |pairs|
   113	  ensures Sort(pairs, less)[|pairs| - 1].0 == MaxFirst(pairs)
   114	{
   115	  var d := Sort(pairs, less);
   116	  SortLastIsMax(pairs, less);
   117	  SortKeepsElems(pairs, less);
   118	  MaxFirstBounds(pairs);
   119	  MaxFirstAttained(pairs);
   120	
   121	  assert d[|d| - 1] in d;
   122	  assert d[|d| - 1] in pairs;              // SortKeepsElems
   123	  assert d[|d| - 1].0 <= MaxFirst(pairs);  // MaxFirstBounds
   124	
   125	  var w :| w in pairs && w.0 == MaxFirst(pairs);
   126	  assert !less(d[|d| - 1], w);             // SortLastIsMax
   127	  assert w.0 <= d[|d| - 1].0;              // the refinement hypothesis
   128	}
   129	
   130	lemma MaxFirstAttained(s: seq<(int, int)>)
   131	  requires |s| > 0
   132	  ensures exists w :: w in s && w.0 == MaxFirst(s)
   133	  decreases |s|
   134	{
   135	  if |s| == 1 { assert s[0] in s && s[0].0 == MaxFirst(s); }
   136	  else {
   137	    MaxFirstAttained(s[1..]);
   138	    var m := MaxFirst(s[1..]);
   139	    if s[0].0 > m { assert s[0] in s && s[0].0 == MaxFirst(s); }
   140	    else {
   141	      var w :| w in s[1..] && w.0 == m;
   142	      assert w in s;
   143	    }
   144	  }
   145	}
   146	
   147	// The outer loop runs `d[|d|-1].0 + 2` times, clamped at zero. That is an
   148	// input VALUE, not a size, so it appears in the bound as its own parameter.
   149	ghost function OuterTrips(pairs: seq<(int, int)>): nat
   150	  requires |pairs| > 0
   151	{
   152	  var m := MaxFirst(pairs) + 2;
   153	  if m > 0 then m else 0
   154	}
   155	
   156	method Solve(n: int, k: int, pairs: seq<(int, int)>) returns (output: string, ghost steps: nat)
   157	  requires |pairs| >= 1
   158	  requires n <= |pairs|
   159	  requires n >= 0
   160	  ensures steps <= 2 * |pairs| * (CeilLog2(|pairs|) + 1)
   161	                 + 12 * OuterTrips(pairs) + 2 * n + 21
   162	{
   163	  ghost var less := (x: (int, int), y: (int, int)) => x.0 < y.0 || (x.0 == y.0 && x.1 < y.1);
   164	  assert StrictTotalOrder(less);
   165	  assert forall a: (int, int), b: (int, int) :: !less(a, b) ==> b.0 <= a.0;
   166	
   167	  SortCostTreeBound(|pairs|);
   168	  var d := Sort(pairs, (x: (int, int), y: (int, int)) => x.0 < y.0 || (x.0 == y.0 && x.1 < y.1));
   169	  assert d == Sort(pairs, less);
   170	  steps := 1 + SortCost(|pairs|);
   171	
   172	  LastIsMaxFirst(pairs, less);
   173	  assert |d| == |pairs|;
   174	
   175	  var cur := 0;
   176	  var nex := 0;
   177	  var idx := 0;
   178	  var r := 0;
   179	  var limit := d[|d| - 1].0 + 2;
   180	  assert limit == MaxFirst(pairs) + 2;
   181	  assert limit <= OuterTrips(pairs);
   182	  steps := steps + 5;
   183	
   184	  ghost var base := steps;
   185	  var i := 0;
   186	  while i < limit
   187	    invariant 0 <= i
   188	    invariant i <= OuterTrips(pairs)   // 0 when limit <= 0, where the loop never runs
   189	    invariant 0 <= idx <= n
   190	    invariant |d| == |pairs|
   191	    invariant limit == MaxFirst(pairs) + 2
   192	    invariant steps <= base + 12 * i + 2 * idx
   193	    decreases limit - i
   194	  {
   195	    nex := 0;
   196	    var p := k;
   197	    while idx < n && d[idx].0 < i
   198	      invariant 0 <= idx <= n
   199	      invariant steps <= base + 12 * i + 2 * idx
   200	      decreases n - idx
   201	    {
   202	      idx := idx + 1;
   203	      steps := steps + 2;
   204	    }
   205	    while idx < n && d[idx].0 == i
   206	      invariant 0 <= idx <= n
   207	      invariant steps <= base + 12 * i + 2 * idx
   208	      decreases n - idx
   209	    {
   210	      nex := nex + d[idx].1;
   211	      idx := idx + 1;
   212	      steps := steps + 2;
   213	    }
   214	    var m1 := if p < cur then p else cur;
   215	    r := r + m1;
   216	    p := p - m1;
   217	    var m2 := if p < nex then p else nex;
   218	    r := r + m2;
   219	    cur := nex - m2;
   220	    i := i + 1;
   221	    steps := steps + 12;
   222	  }
   223	  assert i <= OuterTrips(pairs);
   224	  assert steps <= base + 12 * OuterTrips(pairs) + 2 * n;
   225	
   226	  output := IntToString(r);
   227	  steps := steps + 1;
   228	}
