    36	// SplitCharFrom consumes one character of s per recursive call, so the number
    37	// of pieces it can produce is bounded by the number of characters left plus
    38	// the one piece already carried in acc.
    39	lemma SplitCharFromCount(s: string, sep: char, i: int, cur: string, acc: seq<string>)
    40	  requires 0 <= i <= |s|
    41	  ensures |SplitCharFrom(s, sep, i, cur, acc)| <= |acc| + (|s| - i) + 1
    42	  decreases |s| - i
    43	{
    44	  if i < |s| {
    45	    if s[i] == sep {
    46	      SplitCharFromCount(s, sep, i + 1, "", acc + [cur]);
    47	    } else {
    48	      SplitCharFromCount(s, sep, i + 1, cur + [s[i]], acc);
    49	    }
    50	  }
    51	}
    52	
    53	lemma SplitCharCount(s: string, sep: char)
    54	  ensures |SplitChar(s, sep)| <= |s| + 1
    55	{
    56	  SplitCharFromCount(s, sep, 0, "", []);
    57	}
    58	
    59	method Solve(n: int, k: int, m: int, s: string) returns (output: string, ghost steps: nat)
    60	  ensures steps <= 2 * NLogN(|s| + 1) + 20 * (|s| + 1) + 40
    61	{
    62	  steps := 1;
    63	  var a := k;
    64	  var b := m;
    65	  var pieces := SplitChar(s, '*');
    66	  steps := steps + (|s| + 1);
    67	  SplitCharCount(s, '*');
    68	  var lens := seq(|pieces|, idx requires 0 <= idx < |pieces| => |pieces[idx]|);
    69	  steps := steps + |pieces|;
    70	  var row := Sort(lens, LessInt);
    71	  steps := steps + SortCost(|lens|);
    72	  SortCostWithin(|lens|, |s| + 1);
    73	  assert |row| <= |s| + 1;
    74	  var total := 0;
    75	  var i := 0;
    76	  while i < |row|
    77	    invariant 0 <= i <= |row|
    78	    invariant steps <= 2 * NLogN(|s| + 1) + 6 * |s| + 10 + 6 * i
    79	    decreases |row| - i
    80	  {
    81	    var l := row[i];
    82	    var odd := l / 2 + l % 2;
    83	    var even := l / 2;
    84	    if a > b {
    85	      var da := Min(odd, a);
    86	      var db := Min(even, b);
    87	      total := total + da + db;
    88	      a := a - da;
    89	      b := b - db;
    90	    } else {
    91	      var da := Min(even, a);
    92	      var db := Min(odd, b);
    93	      total := total + da + db;
    94	      a := a - da;
    95	      b := b - db;
    96	    }
    97	    i := i + 1;
    98	    steps := steps + 6;
    99	  }
   100	  output := IntToString(total);
   101	  steps := steps + 1;
   102	}
   103	
   104	
   105	function Min(x: int, y: int): int { if x < y then x else y }
   106	
   107	function LessInt(x: int, y: int): bool { x > y }
   108	
   109	function SplitChar(s: string, sep: char): seq<string>
   110	{
   111	  SplitCharFrom(s, sep, 0, "", [])
   112	}
   113	
   114	function SplitCharFrom(s: string, sep: char, i: int, cur: string, acc: seq<string>): seq<string>
   115	  requires 0 <= i <= |s|
   116	  decreases |s| - i
   117	{
   118	  if i >= |s| then acc + [cur]
   119	  else if s[i] == sep then SplitCharFrom(s, sep, i + 1, "", acc + [cur])
   120	  else SplitCharFrom(s, sep, i + 1, cur + [s[i]], acc)
   121	}
