  SortCostWithin(|neg|, |data_list|);
  SortLen(neg, (p: (int,int), q: (int,int)) => p.0 + p.1 > q.0 + q.1);
  assert SortCost(|neg|) <= 2 * NLogN(|data_list|) + 1;
  steps := steps + SortCost(|neg|);
