  var parts := seq(n, _ => "");
  parts := parts[0 := IntToString(vals[bestIdx])];
  steps := steps + 2;
  var j := 0;
  var pos := 1;
  ghost var b3 := steps;
  while j < n
    invariant 0 <= j <= n
    invariant pos == j + 1 - (if bestIdx < j then 1 else 0)
    invariant |parts| == n
    invariant steps <= b3 + 4 * j
    decreases n - j
  {
    if j != bestIdx {
      parts := parts[pos := IntToString(vals[j])];
      pos := pos + 1;
    }
    j := j + 1;
    steps := steps + 4;
  }
  output := Join(parts, " ") + "\n";
  steps := steps + 12 * n + 2; // Join charge: each part is IntToString of a
