  } else {
    MaxLenBound(xs[1..], x);
  }
}

// Isolated so Z3 never has to discover the distributive step itself.
lemma DistribStep(idx: int, m: int)
  requires idx >= 1
  ensures 6 * (idx - 1) * m + 6 * m == 6 * idx * m
{}

